<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
require_role(['admin','collector','expert']);
require_once __DIR__.'/../app/Services/CsvImporter.php';

$types=['computer'=>'رایانه','printer'=>'چاپگر','scanner'=>'اسکنر','display'=>'نمایشگر'];
$steps=['computer','printer','scanner','display'];
$step=(string)($_GET['step']??$_POST['step']??'computer');
if(!in_array($step,$steps,true))$step='computer';
if(!can_manage_asset_type($step,'create')){http_response_code(403);exit('برای این مرحله دسترسی ثبت ندارید.');}
$importer=new CsvImporter();
$wizard=$_SESSION['_hardware_wizard']??['records'=>[],'meta'=>[]];
$error=null;$message=null;
$arrayFields=CsvImporter::arrayFields();

if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 $action=(string)($_POST['action']??'');
 if($action==='reset'){unset($_SESSION['_hardware_wizard']);redirect('asset_wizard.php');}
 if($action==='analyze'){
  if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)$error='فایل CSV این مرحله انتخاب نشده یا قابل دریافت نیست.';
  else try{
   if(strtolower(pathinfo($_FILES['csv']['name'],PATHINFO_EXTENSION))!=='csv')throw new RuntimeException('فقط فایل CSV قابل بارگذاری است.');
   $rows=$importer->rows($_FILES['csv']['tmp_name']);$row=$rows->current();if(!$row)throw new RuntimeException('فایل داده‌ای ندارد.');
   if(in_array($step,['printer','scanner'],true)){$row['IPAddresses']=[];unset($row['MACAddresses']);}
   $wizard['records'][$step]=$row;$wizard['records'][$step]['_source_file']=basename($_FILES['csv']['name']);
   $_SESSION['_hardware_wizard']=$wizard;redirect('asset_wizard.php?step='.$step);
  }catch(Throwable $e){$error=$e->getMessage();}
 }
 if($action==='next'){
  $record=$wizard['records'][$step]??[];
  foreach(($_POST['technical']??[]) as $k=>$v){$s=trim((string)$v);if(in_array($k,$arrayFields,true)){ $d=json_decode($s,true);$record[$k]=(json_last_error()===JSON_ERROR_NONE&&is_array($d))?array_values($d):$importer->split($s);}else $record[$k]=$s;}
  $record['asset_no']=trim((string)($_POST['asset_no']??''));$record['location']=trim((string)($_POST['location']??''));$record['department']=trim((string)($_POST['department']??''));$record['personnel_id']=trim((string)($_POST['personnel_id']??''));$record['device_subtype']=trim((string)($_POST['device_subtype']??''));
  if(!preg_match('/^\d{7}$/',$record['asset_no']))$error='شماره اموال این تجهیز باید دقیقاً ۷ رقم باشد.';
  else{$wizard['records'][$step]=$record;$_SESSION['_hardware_wizard']=$wizard;$i=array_search($step,$steps,true);if($i<count($steps)-1)redirect('asset_wizard.php?step='.$steps[$i+1]);else redirect('asset_wizard.php?step=review');}
 }
 if($action==='finish'){
  $records=$wizard['records'];$missing=array_values(array_diff($steps,array_keys($records)));if($missing){$error='هنوز تحلیل همه چهار پایگاه تکمیل نشده است.';}
  else{
   $all=[];foreach($steps as $t){$no=trim((string)($records[$t]['asset_no']??''));if(!preg_match('/^\d{7}$/',$no))$all[]=$types[$t].': شماره اموال ۷ رقمی وارد نشده است.';}
   $nos=[];foreach($steps as $t){$no=$records[$t]['asset_no'];if(isset($nos[$no]))$all[]='شماره اموال '.$no.' برای دو تجهیز تکرار شده است.';$nos[$no]=true;}
   if($all)$error=implode(' | ',$all);
   else try{
    db()->beginTransaction();
    foreach($steps as $t){$r=$records[$t];$no=$r['asset_no'];$check=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$check->execute([$no]);if($check->fetchColumn())throw new RuntimeException('شماره اموال '.$no.' از قبل ثبت شده است.');
     $technical=[];foreach($r as $k=>$v){if(str_starts_with((string)$k,'_')||in_array($k,['asset_no','location','department','personnel_id','device_subtype'],true))continue;$technical[$k]=$v;}
     $usage=['BootCount'=>'boot_count','NormalShutdownCount'=>'normal_shutdown_count','UnexpectedShutdownCount'=>'unexpected_shutdown_count','UserShutdownCount'=>'user_shutdown_count','LastBootTime'=>'last_boot_time','LastShutdownTime'=>'last_shutdown_time','CompletedSessionCount'=>'completed_session_count','CurrentSessionHours'=>'current_session_hours','CurrentSessionDuration'=>'current_session_duration','TotalUsageHours'=>'total_usage_hours','TotalUsageDuration'=>'total_usage_duration','AverageSessionHours'=>'average_session_hours','AverageSessionDuration'=>'average_session_duration','LongestSessionHours'=>'longest_session_hours','LongestSessionDuration'=>'longest_session_duration','CollectedAt'=>'collected_at'];
     $cols=['asset_no','asset_type','device_subtype','hostname','personnel_id','location','department','manufacturer','model','serial_no','technical','status','source_file','created_by','updated_by'];$vals=[$no,$t,trim((string)($r['device_subtype']??''),),$r['ComputerName']??$r['PrinterName']??$r['ScannerName']??$r['DisplayName']??null,($r['personnel_id']??'')!==''?(int)$r['personnel_id']:null,$r['location']??'', $r['department']??'', $r['Manufacturer']??$r['PrinterManufacturer']??$r['DisplayManufacturer']??$r['ScannerManufacturer']??'', $r['Model']??$r['PrinterModel']??$r['DisplayModel']??$r['ScannerModel']??'', $r['SystemSerial']??$r['PrinterSerial']??$r['DisplaySerial']??$r['ScannerSerial']??'',json_encode($technical,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),'active',$r['_source_file']??null,user()['id'],user()['id']];
     foreach($usage as $src=>$col){$cols[]=$col;$vals[]=($r[$src]??'')===''?null:$r[$src];}
     $marks=implode(',',array_fill(0,count($cols),'?'));db()->prepare('INSERT INTO assets('.implode(',',$cols).') VALUES('.$marks.')')->execute($vals);
     foreach($importer->disks($r) as $d)db()->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)')->execute([$no,$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);
     foreach($importer->ramSlots($r) as $x)db()->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$no,$x['slot_no'],$x['state']??'unknown',$x['capacity_gb']??null,$x['ram_type']??null,$x['speed_mhz']??null,$x['manufacturer']??null,$x['part_number']??null,$x['serial_no']??null]);
     audit('hardware_wizard_asset_created','asset',$no,['type'=>$t,'source'=>$r['_source_file']??null]);
    }
    db()->commit();unset($_SESSION['_hardware_wizard']);flash('success','هر چهار پایگاه با موفقیت ثبت شدند.');redirect('index.php');
   }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}
  }
 }
}
$wizard=$_SESSION['_hardware_wizard']??['records'=>[],'meta'=>[]];
if($step==='review'){
 ?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تأیید نهایی ثبت تجهیزات</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">مرحله نهایی</div><h1>بازبینی و تأیید نهایی</h1><p class="muted">تا قبل از تأیید، هیچ‌کدام از چهار تجهیز در پایگاه ثبت قطعی نمی‌شوند.</p></div></div><div class="wizard-steps"><?php foreach($steps as $s):?><a class="wizard-step done" href="asset_wizard.php?step=<?=$s?>"><b><?=array_search($s,$steps)+1?></b><span><?=$types[$s]?></span></a><?php endforeach;?></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="review-grid"><?php foreach($steps as $s):$r=$wizard['records'][$s]??[];?><article class="panel review-card"><div class="section-title"><h2><?=$types[$s]?></h2><a class="btn small" href="asset_wizard.php?step=<?=$s?>">ویرایش</a></div><div class="review-fields"><div><span>شماره اموال</span><strong><?=e($r['asset_no']??'—')?></strong></div><div><span>نام/Host</span><strong><?=e($r['ComputerName']??$r['PrinterName']??$r['ScannerName']??$r['DisplayName']??'—')?></strong></div><div><span>مدل</span><strong><?=e($r['Model']??$r['PrinterModel']??$r['ScannerModel']??$r['DisplayModel']??'—')?></strong></div><div><span>مکان</span><strong><?=e($r['location']??'—')?></strong></div></div></article><?php endforeach;?></section><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="finish"><input type="hidden" name="step" value="review"><div class="actions sticky-confirm"><button class="btn primary" type="submit">✓ تأیید نهایی و ثبت هر چهار تجهیز</button><button class="btn" type="submit" name="action" value="reset">شروع مجدد</button></div></form></main></body></html><?php exit;}
$r=$wizard['records'][$step]??[];$people=db()->query('SELECT id,full_name,personnel_code,department FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();
$labels=['SystemType'=>'نوع سیستم','OSName'=>'نام سیستم‌عامل','OSVersion'=>'نسخه سیستم‌عامل','OSBuild'=>'Build','OSArchitecture'=>'معماری','CPUName'=>'پردازنده','CPUManufacturer'=>'سازنده CPU','CPUCores'=>'هسته فیزیکی','CPULogicalProcessors'=>'پردازنده منطقی','CPUMaxClockMHz'=>'فرکانس CPU (MHz)','RAMTotalGB'=>'RAM کل (GB)','RAMSlotCount'=>'تعداد اسلات RAM','RAMInstalledSlots'=>'اسلات‌های پر','RAMType'=>'نوع RAM','MotherboardManufacturer'=>'سازنده مادربرد','MotherboardProduct'=>'مدل مادربرد','MotherboardVersion'=>'نسخه مادربرد','MotherboardSerial'=>'سریال مادربرد','BIOSManufacturer'=>'سازنده BIOS','BIOSVersion'=>'نسخه BIOS','BIOSSerial'=>'سریال BIOS','BIOSReleaseDate'=>'تاریخ BIOS','LogicalDriveDetails'=>'درایوهای منطقی','NetworkDetails'=>'جزئیات شبکه','IPAddresses'=>'IP','MACAddresses'=>'MAC','SubnetMasks'=>'Subnet','Gateways'=>'Gateway','DNSServers'=>'DNS','GPUDetails'=>'GPU','SoundDetails'=>'کارت صدا','MonitorDetails'=>'نمایشگر متصل','PageFileDetails'=>'Page File','AntivirusDetails'=>'آنتی‌ویروس','BootCount'=>'تعداد بوت','NormalShutdownCount'=>'خاموشی عادی','UnexpectedShutdownCount'=>'خاموشی غیرمنتظره','UserShutdownCount'=>'خاموشی کاربر','LastBootTime'=>'آخرین Boot','LastShutdownTime'=>'آخرین Shutdown','CompletedSessionCount'=>'جلسات کامل','CurrentSessionHours'=>'جلسه فعلی (ساعت)','CurrentSessionDuration'=>'مدت جلسه فعلی','TotalUsageHours'=>'کل استفاده (ساعت)','TotalUsageDuration'=>'کل مدت استفاده','AverageSessionHours'=>'میانگین جلسه (ساعت)','AverageSessionDuration'=>'میانگین مدت جلسه','LongestSessionHours'=>'طولانی‌ترین جلسه (ساعت)','LongestSessionDuration'=>'مدت طولانی‌ترین جلسه','CollectedAt'=>'زمان جمع‌آوری','PrinterType'=>'نوع چاپگر','PrinterCapabilities'=>'قابلیت‌ها','ColorMode'=>'رنگی/سیاه‌وسفید','Connection'=>'نوع اتصال','NetworkSharing'=>'اشتراک‌گذاری شبکه','Duplex'=>'چاپ دورو','DisplayTechnology'=>'فناوری نمایشگر','DisplaySize'=>'اندازه نمایشگر','DisplayResolution'=>'رزولوشن','DisplaySerial'=>'سریال نمایشگر','ScannerType'=>'نوع اسکنر','ScannerResolution'=>'رزولوشن اسکنر','ScannerConnection'=>'اتصال اسکنر','ScannerDuplex'=>'اسکن دورو'];
$groups=['computer'=>['سیستم و کاربر'=>['SystemType','Domain'],'سیستم‌عامل'=>['OSName','OSVersion','OSBuild','OSArchitecture'],'پردازنده'=>['CPUName','CPUManufacturer','CPUCores','CPULogicalProcessors','CPUMaxClockMHz'],'حافظه RAM'=>['RAMTotalGB','RAMSlotCount','RAMInstalledSlots','RAMType','RAMManufacturers','RAMPartNumbers','RAMSerialNumbers','RAMSpeedsMHz','RAMSlotDetails'],'مادربرد'=>['MotherboardManufacturer','MotherboardProduct','MotherboardVersion','MotherboardSerial'],'BIOS'=>['BIOSManufacturer','BIOSVersion','BIOSSerial','BIOSReleaseDate'],'شبکه'=>['NetworkDetails','IPAddresses','MACAddresses','SubnetMasks','Gateways','DNSServers'],'تجهیزات جانبی'=>['GPUDetails','SoundDetails','MonitorDetails','PageFileDetails','AntivirusDetails'],'پایش استفاده'=>['BootCount','NormalShutdownCount','UnexpectedShutdownCount','UserShutdownCount','LastBootTime','LastShutdownTime','CompletedSessionCount','CurrentSessionHours','CurrentSessionDuration','TotalUsageHours','TotalUsageDuration','AverageSessionHours','AverageSessionDuration','LongestSessionHours','LongestSessionDuration','CollectedAt']], 'printer'=>['مشخصات چاپگر'=>['PrinterType','PrinterCapabilities','ColorMode','Connection','NetworkSharing','Duplex','IPAddresses']], 'scanner'=>['مشخصات اسکنر'=>['ScannerType','ScannerResolution','ScannerConnection','ScannerDuplex','IPAddresses']], 'display'=>['مشخصات نمایشگر'=>['DisplayTechnology','DisplaySize','DisplayResolution','DisplaySerial','Connection']]];
function wizval(array $r,string $k):string{ $v=$r[$k]??'';if(is_array($v))return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);return (string)$v;}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تحلیل مرحله‌ای CSV | <?=$types[$step]?></title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><?php if((user()['role']??'')==='admin'):?><a href="users.php">کاربران</a><a href="directory.php">Active Directory</a><?php endif;?><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">ثبت یکپارچه چهار پایگاه</div><h1>تحلیل <?=$types[$step]?></h1><p class="muted">فایل‌ها مرحله‌به‌مرحله تحلیل می‌شوند و فقط در مرحله تأیید نهایی ثبت قطعی خواهند شد.</p></div></div><div class="wizard-steps"><?php foreach($steps as $s):$done=isset($wizard['records'][$s]);$active=$s===$step;?><a class="wizard-step <?=$done?'done':''?> <?=$active?'active':''?>" href="asset_wizard.php?step=<?=$s?>"><b><?=array_search($s,$steps)+1?></b><span><?=$types[$s]?></span></a><?php endforeach;?><a class="wizard-step review" href="asset_wizard.php?step=review"><b>✓</b><span>تأیید نهایی</span></a></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="panel"><h2>۱. بارگذاری و تحلیل فایل</h2><form method="post" enctype="multipart/form-data" class="upload-row"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=$step?>"><input type="hidden" name="action" value="analyze"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn" type="submit">تحلیل و خواندن CSV</button></form><?php if(isset($r['_source_file'])):?><p class="muted">فایل تحلیل‌شده: <?=e($r['_source_file'])?></p><?php endif;?></section><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=$step?>"><input type="hidden" name="action" value="next"><section class="panel"><div class="section-title"><div><h2>۲. تکمیل و ویرایش اطلاعات</h2><p class="muted">مقادیر چندتایی با JSON قابل ویرایش هستند.</p></div></div><div class="form-grid"><label>شماره اموال *<input name="asset_no" value="<?=e($r['asset_no']??'')?>" inputmode="numeric" pattern="\d{7}" maxlength="7" required></label><label>زیرنوع<input name="device_subtype" value="<?=e($r['device_subtype']??'')?>"></label><label>مکان<input name="location" value="<?=e($r['location']??'')?>" required></label><label>دانشکده/اداره/گروه<input name="department" value="<?=e($r['department']??'')?>"></label><?php if($step==='computer'):?><label>پرسنل<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=((string)($r['personnel_id']??'')===(string)$p['id'])?'selected':''?>><?=e($p['full_name'].' — '.($p['personnel_code']??''))?></option><?php endforeach;?></select></label><?php endif;?></div><?php foreach($groups[$step] as $title=>$keys):?><div class="wizard-group"><h3><?=e($title)?></h3><div class="form-grid three-cols"><?php foreach($keys as $k):if(!array_key_exists($k,$r))continue;$array=in_array($k,$arrayFields,true);?><label><?=e($labels[$k]??$k)?><textarea name="technical[<?=e($k)?>]" rows="<?=($array||$k==='NetworkDetails'||$k==='RAMSlotDetails')?'4':'2'?>" <?=$array?'dir="ltr"':''?>><?=e(wizval($r,$k))?></textarea></label><?php endforeach;?></div></div><?php endforeach;?></section><div class="actions sticky-confirm"><button class="btn primary" type="submit"><?php $i=array_search($step,$steps,true);echo $i<count($steps)-1?'ذخیره مرحله و رفتن به مرحله بعد':'ذخیره مرحله و رفتن به تأیید نهایی';?></button><button class="btn" type="submit" name="action" value="reset">شروع مجدد</button></div></form></main></body></html>
